CREATE TABLE IF NOT EXISTS authentication (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, uuid VARCHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL);
ALTER TABLE authentication ADD CONSTRAINT authentication_user_id_unique UNIQUE (user_id);
CREATE TABLE IF NOT EXISTS auth_device (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_auth_id BIGINT NOT NULL, device_uuid VARCHAR(36) NOT NULL, device_name VARCHAR(255) NOT NULL, refresh_token_id VARCHAR(36) NULL, is_signed_in BOOLEAN NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_auth_device_user_auth_id__id FOREIGN KEY (user_auth_id) REFERENCES authentication(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX auth_device_user_auth_id ON auth_device (user_auth_id);
ALTER TABLE auth_device ADD CONSTRAINT auth_device_user_auth_id_device_uuid_unique UNIQUE (user_auth_id, device_uuid);
CREATE TABLE IF NOT EXISTS auth_to_handle (id BIGINT AUTO_INCREMENT PRIMARY KEY, auth_id BIGINT NOT NULL, handle VARBINARY(64) NOT NULL, CONSTRAINT fk_auth_to_handle_auth_id__id FOREIGN KEY (auth_id) REFERENCES authentication(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS passkey_credentials (id BIGINT AUTO_INCREMENT PRIMARY KEY, identity_id BIGINT NOT NULL, cred_descriptor_id VARBINARY(24) NOT NULL, cred_descriptor_type VARCHAR(255) NOT NULL, cred_descriptor_transports VARCHAR(255) NOT NULL, public_key VARBINARY(255) NOT NULL, signature_count BIGINT NOT NULL, discoverable BOOLEAN NOT NULL, backup_eligible BOOLEAN NOT NULL, backed_up BOOLEAN NOT NULL, attestation_object VARBINARY(255) NOT NULL, client_data VARBINARY(255) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_passkey_credentials_identity_id__id FOREIGN KEY (identity_id) REFERENCES auth_to_handle(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE passkey_credentials ADD CONSTRAINT passkey_credentials_identity_id_cred_descriptor_id_unique UNIQUE (identity_id, cred_descriptor_id);
